def encode_base62(num: int) -> str:
    if not isinstance(num, int) or num < 0:
        raise ValueError('Number must be a non-negative integer')
    if num == 0:
        return CHARS[0]
    res = []
    while num > 0:
        res.append(CHARS[num % 62])
        num //= 62
    return ''.join(reversed(res))

