class SlidingWindowRateLimiter:
    def __init__(self, limit: int, window_sec: float):
        self.limit = limit
        self.window_sec = window_sec
        self.history = {}
    def allow_request(self, key: str, now: float) -> bool:
        if key not in self.history:
            self.history[key] = []
        timestamps = self.history[key]
        threshold = now - self.window_sec
        valid_ts = [t for t in timestamps if t > threshold]
        if len(valid_ts) < self.limit:
            valid_ts.append(now)
            self.history[key] = valid_ts
            return True
        self.history[key] = valid_ts
        return False

