class StampedeProtectedCache:
    def __init__(self):
        self.cache = {}
    def get_or_compute(self, key: str, loader_fn, now: float, ttl: float = 60.0, beta: float = 1.0, compute_time: float = 0.5):
        if key in self.cache:
            val, expiry, delta = self.cache[key]
            if now >= expiry or (now + delta * beta >= expiry):
                val = loader_fn()
                self.cache[key] = (val, now + ttl, delta)
            return val
        val = loader_fn()
        self.cache[key] = (val, now + ttl, compute_time)
        return val

