    def __init__(self, capacity: int, refill_rate: float):
        self.capacity = float(capacity)
        self.refill_rate = float(refill_rate)
        self.buckets = {}
    def acquire(self, key: str, tokens: int = 1, now: float = 0.0) -> bool:
        if key not in self.buckets:
            self.buckets[key] = (self.capacity, now)
        current_tokens, last_time = self.buckets[key]
        elapsed = max(0.0, now - last_time)
        current_tokens = min(self.capacity, current_tokens + elapsed * self.refill_rate)
        if current_tokens >= tokens:
            self.buckets[key] = (current_tokens - tokens, now)
            return True
        self.buckets[key] = (current_tokens, now)
        return False

