class CircuitBreaker:
    def __init__(self, failure_threshold: int = 3, recovery_time: float = 10.0):
        self.threshold = failure_threshold
        self.recovery_time = recovery_time
        self.state = 'CLOSED'
        self.failure_count = 0
        self.last_failure_time = 0.0
    def call(self, func, now: float, *args, **kwargs):
        if self.state == 'OPEN':
            if now - self.last_failure_time >= self.recovery_time:
                self.state = 'HALF_OPEN'
            else:
                raise RuntimeError('Circuit is OPEN')
        try:
            res = func(*args, **kwargs)
            if self.state == 'HALF_OPEN':
                self.state = 'CLOSED'
                self.failure_count = 0
            return res
        except Exception as e:
            self.last_failure_time = now
            self.failure_count += 1
            if self.state in ('CLOSED', 'HALF_OPEN') and (self.failure_count >= self.threshold or self.state == 'HALF_OPEN'):
                self.state = 'OPEN'
            raise e

