class OutboxProcessor:
    def __init__(self, db_session, message_bus):
        self.db = db_session
        self.bus = message_bus
        self.events = []
        self._id_counter = 1
    def record_event(self, aggregate_id: str, event_type: str, payload: dict) -> int:
        eid = self._id_counter
        self._id_counter += 1
        self.events.append({
            'id': eid,
            'aggregate_id': aggregate_id,
            'event_type': event_type,
            'payload': payload,
            'status': 'PENDING'
        })
        return eid
    def publish_pending(self) -> int:
        sent = 0
        for evt in self.events:
            if evt['status'] == 'PENDING':
                try:
                    self.bus.publish(evt)
                    evt['status'] = 'PROCESSED'
                    sent += 1
                except Exception:
                    evt['status'] = 'FAILED'
        return sent

