        self.steps.append({'name': name, 'action': action_fn, 'compensate': compensate_fn})
    def execute(self, context: dict) -> dict:
        executed = []
        for step in self.steps:
            try:
                step['action'](context)
                executed.append(step)
            except Exception as e:
                for completed in reversed(executed):
                    try:
                        completed['compensate'](context)
                    except Exception:
