def normalize_phone(raw_phone, default_country_code='+7'):
    if not raw_phone or not isinstance(raw_phone, str):
        raise ValueError('Invalid phone number')

    cleaned = raw_phone.strip()
    has_plus = cleaned.startswith('+')
    digits = [ch for ch in cleaned if ch.isdigit()]

    # Проверка на недопустимые буквы
    allowed_chars = set('0123456789+ -().')
    if any(ch not in allowed_chars for ch in cleaned):
        raise ValueError('Invalid phone number')

    digit_str = ''.join(digits)
    if not digit_str:
        raise ValueError('Invalid phone number')

    if len(digit_str) == 10:
        prefix = default_country_code if default_country_code.startswith('+') else f'+{default_country_code}'
        return f'{prefix}{digit_str}'

    if len(digit_str) == 11 and digit_str.startswith('8'):
        return f'+7{digit_str[1:]}'

    if len(digit_str) == 11 and digit_str.startswith('7'):
        return f'+{digit_str}'

    if has_plus and 10 <= len(digit_str) <= 15:
        return f'+{digit_str}'

    raise ValueError('Invalid phone number')

