def filter_audit_records(records, min_level='INFO', required_tags=None, exclude_bots=True):
    level_weights = {
        'DEBUG': 10,
        'INFO': 20,
        'WARNING': 30,
        'ERROR': 40,
        'CRITICAL': 50
    }
    min_weight = level_weights.get(min_level.upper(), 20)
    req_tags_set = set(required_tags) if required_tags else set()

    result = []
    for rec in records:
        rec_level = rec.get('level', 'INFO').upper()
        if level_weights.get(rec_level, 0) < min_weight:
            continue

        if req_tags_set:
            rec_tags = set(rec.get('tags', []))
            if not req_tags_set.issubset(rec_tags):
                continue

        if exclude_bots:
            if rec.get('is_bot') is True:
                continue
            ua = str(rec.get('user_agent', '')).lower()
            if 'bot' in ua:
                continue

        result.append(dict(rec))
    return result

