class ConnectionPoolManager:
    _instances = {}

    def __new__(cls, cluster_name='default'):
        if cluster_name not in cls._instances:
            inst = super().__new__(cls)
            inst.cluster_name = cluster_name
            inst.connections = []
            inst._counter = 1
            cls._instances[cluster_name] = inst
        return cls._instances[cluster_name]

    def acquire(self):
        if self.connections:
            return self.connections.pop()
        conn = f'{self.cluster_name}-conn-{self._counter}'
        self._counter += 1
        return conn

    def release(self, conn_str):
        self.connections.append(conn_str)

    @classmethod
    def clear_all_pools(cls):
        cls._instances.clear()

