class DependencyContainer:
    def __init__(self):
        self._singletons = {}  # name -> {'factory': fn, 'instance': obj}
        self._transients = {}  # name -> factory_fn
        self._overrides = {}   # name -> explicit_obj

    def register_singleton(self, name, factory_func):
        self._singletons[name] = {'factory': factory_func, 'instance': None}

    def register_transient(self, name, factory_func):
        self._transients[name] = factory_func

    def has(self, name):
        return name in self._overrides or name in self._singletons or name in self._transients

    def override(self, name, instance):
        self._overrides[name] = instance

    def resolve(self, name):
        if name in self._overrides:
            return self._overrides[name]

        if name in self._singletons:
            entry = self._singletons[name]
            if entry['instance'] is None:
                entry['instance'] = entry['factory'](self)
            return entry['instance']

        if name in self._transients:
            return self._transients[name](self)

        raise KeyError(f'Dependency not registered: {name}')

    def clear(self):
        self._singletons.clear()
        self._transients.clear()
        self._overrides.clear()

