import json
import zlib

class CompressionStrategy:
    def pack(self, data: dict) -> bytes:
        raise NotImplementedError
    def unpack(self, raw_bytes: bytes) -> dict:
        raise NotImplementedError


class JsonUtf8Strategy(CompressionStrategy):
    def pack(self, data: dict) -> bytes:
        s = json.dumps(data, sort_keys=True)
        return s.encode('utf-8')

    def unpack(self, raw_bytes: bytes) -> dict:
        try:
            s = raw_bytes.decode('utf-8')
            return json.loads(s)
        except Exception as e:
            raise ValueError('Unpack failed') from e


class ZlibCompressedJsonStrategy(CompressionStrategy):
    def __init__(self):
        self._json_strat = JsonUtf8Strategy()

    def pack(self, data: dict) -> bytes:
        raw = self._json_strat.pack(data)
        return zlib.compress(raw)

    def unpack(self, raw_bytes: bytes) -> dict:
        try:
            decompressed = zlib.decompress(raw_bytes)
            return self._json_strat.unpack(decompressed)
        except Exception as e:
