class RoundRobinStrategy(BalancingStrategy):
    def __init__(self):
        self._idx = 0

    def select_node(self, nodes: list, request_context: dict):
        if not nodes:
            return None
        chosen = nodes[self._idx % len(nodes)]
        self._idx = (self._idx + 1) % len(nodes)
        return chosen


