import math

def _strat_avg(values):
    if not values:
        return 0.0
    return round(sum(values) / len(values), 2)

def _strat_sum(values):
    if not values:
        return 0.0
    return round(sum(values), 2)

def _strat_p95(values):
    if not values:
        return 0.0
    s = sorted(values)
    idx = int(math.ceil(0.95 * len(s))) - 1
    idx = max(0, min(idx, len(s) - 1))
    return round(float(s[idx]), 2)

def _strat_max(values):
    if not values:
        return 0.0
    return round(float(max(values)), 2)

def _strat_min(values):
    if not values:
        return 0.0
    return round(float(min(values)), 2)


class MetricsAggregator:
    def __init__(self):
        self._strategies = {
            'avg': _strat_avg,
            'sum': _strat_sum,
            'p95': _strat_p95,
            'max': _strat_max,
            'min': _strat_min
        }

    def register_metric(self, name: str, strategy_fn):
        self._strategies[name.lower()] = strategy_fn

    def compute(self, metric_name: str, values: list) -> float:
        key = metric_name.lower()
        if key not in self._strategies:
            raise ValueError(f'Unknown metric: {metric_name}')
        return self._strategies[key](values)

