class EventBus:
    def __init__(self):
        self._subscribers = {}  # event_name -> list of handlers

    def subscribe(self, event_name: str, handler_fn):
        if event_name not in self._subscribers:
            self._subscribers[event_name] = []
        handlers = self._subscribers[event_name]
        if handler_fn not in handlers:
            handlers.append(handler_fn)

        def unsubscribe():
            if handler_fn in handlers:
                handlers.remove(handler_fn)
        return unsubscribe

    def publish(self, event_name: str, payload: dict):
        handlers = list(self._subscribers.get(event_name, []))
        for h in handlers:
            h(payload)

    def listener_count(self, event_name: str) -> int:
        return len(self._subscribers.get(event_name, []))

