class AdvancedEventDispatcher:
    def __init__(self):
        self._subscriptions = []  # list of dicts

    def subscribe(self, topic: str, handler_fn, predicate=None):
        entry = {
            'topic': topic,
            'handler': handler_fn,
            'predicate': predicate,
            'once': False
        }
        self._subscriptions.append(entry)
        def unsub():
            if entry in self._subscriptions:
                self._subscriptions.remove(entry)
        return unsub

    def subscribe_once(self, topic: str, handler_fn, predicate=None):
        entry = {
            'topic': topic,
            'handler': handler_fn,
            'predicate': predicate,
            'once': True
        }
        self._subscriptions.append(entry)
        def unsub():
            if entry in self._subscriptions:
                self._subscriptions.remove(entry)
        return unsub

    def _matches(self, sub_topic: str, pub_topic: str) -> bool:
        if sub_topic == pub_topic:
            return True
        if sub_topic.endswith('.*'):
            prefix = sub_topic[:-2]
            return pub_topic.startswith(prefix + '.')
        return False

    def publish(self, topic: str, payload: dict):
        to_remove = []
        for sub in list(self._subscriptions):
            if self._matches(sub['topic'], topic):
                pred = sub['predicate']
                if pred is not None:
                    try:
                        if not pred(payload):
                            continue
                    except Exception:
                        continue
                sub['handler'](payload)
                if sub['once']:
                    to_remove.append(sub)
        for item in to_remove:
            if item in self._subscriptions:
                self._subscriptions.remove(item)

    def active_subscribers_count(self, topic: str) -> int:
        return sum(1 for s in self._subscriptions if s['topic'] == topic)

