import functools
from collections import OrderedDict

def custom_lru_cache(maxsize=128):
    def decorator(fn):
        cache = OrderedDict()
        stats = {'hits': 0, 'misses': 0}

        def _make_key(args, kwargs):
            return (args, tuple(sorted(kwargs.items())))

        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            if key in cache:
                stats['hits'] += 1
                cache.move_to_end(key)
                return cache[key]
            stats['misses'] += 1
            res = fn(*args, **kwargs)
            cache[key] = res
            cache.move_to_end(key)
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return res

        def cache_clear():
            cache.clear()
            stats['hits'] = 0
            stats['misses'] = 0

        def cache_info():
            return {
                'hits': stats['hits'],
                'misses': stats['misses'],
                'size': len(cache),
                'maxsize': maxsize
            }

        def invalidate(*args, **kwargs):
            key = _make_key(args, kwargs)
            if key in cache:
                del cache[key]
                return True
            return False

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        wrapper.invalidate = invalidate
        return wrapper
    return decorator

