import functools
import inspect

def validate_params(**schema):
    def decorator(fn):
        sig = inspect.signature(fn)

        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()
            arguments = bound.arguments

            for name, rule in schema.items():
                if name in arguments:
                    val = arguments[name]
                    if isinstance(rule, tuple):
                        type_cls, validator = rule
                        strip = False
                    elif isinstance(rule, dict):
                        type_cls = rule.get('type')
                        validator = rule.get('validator')
                        strip = rule.get('strip', False)
                    else:
                        continue

                    if strip and isinstance(val, str):
                        val = val.strip()
                        arguments[name] = val

                    if type_cls is not None and not isinstance(val, type_cls):
                        raise TypeError(f'Invalid type for {name}')

                    if validator is not None:
                        try:
                            ok = validator(val)
                            if not ok:
                                raise ValueError(f'Validation failed for {name}')
                        except Exception as e:
                            if isinstance(e, ValueError):
                                raise
                            raise ValueError(f'Validation failed for {name}') from e

            return fn(*bound.args, **bound.kwargs)
        return wrapper
    return decorator

