class Money:
    def __init__(self, amount_cents: int, currency: str = 'RUB'):
        if not isinstance(amount_cents, int) or isinstance(amount_cents, bool):
            raise ValueError('Amount must be non-negative integer cents')
        if amount_cents < 0:
            raise ValueError('Amount must be non-negative integer cents')
        if not isinstance(currency, str) or len(currency.strip()) != 3:
            raise ValueError('Invalid currency code')
        curr = currency.strip().upper()
        if not curr.isalpha():
            raise ValueError('Invalid currency code')

        super().__setattr__('_amount_cents', amount_cents)
        super().__setattr__('_currency', curr)

    @property
    def amount_cents(self) -> int:
        return self._amount_cents

    @property
    def currency(self) -> str:
        return self._currency

    def __setattr__(self, name, value):
        raise AttributeError('Money is immutable')

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._amount_cents == other._amount_cents and self._currency == other._currency

    def __hash__(self):
        return hash((self._amount_cents, self._currency))

    def add(self, other: 'Money') -> 'Money':
        if not isinstance(other, Money) or self._currency != other._currency:
            raise ValueError('Currency mismatch')
        return Money(self._amount_cents + other._amount_cents, self._currency)

    def subtract(self, other: 'Money') -> 'Money':
        if not isinstance(other, Money) or self._currency != other._currency:
            raise ValueError('Currency mismatch')
        if self._amount_cents < other._amount_cents:
            raise ValueError('Insufficient funds')
        return Money(self._amount_cents - other._amount_cents, self._currency)

    def format(self) -> str:
        return f'{self._amount_cents / 100:.2f} {self._currency}'

