class OrderAggregate:
    def __init__(self, order_id: int, max_items_limit: int = 10):
        self._order_id = order_id
        self._max_items_limit = max_items_limit
        self._items = []
        self._status = 'DRAFT'

    @property
    def order_id(self) -> int:
        return self._order_id

    @property
    def status(self) -> str:
        return self._status

    @property
    def items(self) -> list:
        return [OrderItem(it.product_id, it.unit_price, it.quantity) for it in self._items]

    @property
    def total_amount(self) -> float:
        return round(sum(it.subtotal for it in self._items), 2)

    def add_item(self, product_id: int, unit_price: float, quantity: int):
        if self._status != 'DRAFT':
            raise ValueError('Order is not in draft status')
        if quantity <= 0 or unit_price <= 0:
            raise ValueError('Invalid price or quantity')

        current_qty = sum(it.quantity for it in self._items)
        if current_qty + quantity > self._max_items_limit:
            raise ValueError('Order items limit exceeded')

        for it in self._items:
            if it.product_id == product_id:
                it.quantity += quantity
                return
        self._items.append(OrderItem(product_id, unit_price, quantity))

    def submit(self):
        if self._status != 'DRAFT':
            raise ValueError('Order is not in draft status')
        if not self._items:
            raise ValueError('Cannot submit empty order')
        self._status = 'SUBMITTED'

