class BankAccountAggregate:
    def __init__(self, account_id: str, balance_cents: int, is_frozen: bool = False):
        if balance_cents < 0:
            raise ValueError('Initial balance cannot be negative')
        self.account_id = account_id
        self._balance_cents = balance_cents
        self.is_frozen = is_frozen

    @property
    def balance_cents(self) -> int:
        return self._balance_cents

    def deposit(self, amount_cents: int):
        if self.is_frozen:
            raise ValueError('Account is frozen')
        if amount_cents <= 0:
            raise ValueError('Deposit amount must be positive')
        self._balance_cents += amount_cents

    def withdraw(self, amount_cents: int):
        if self.is_frozen:
            raise ValueError('Account is frozen')
        if amount_cents <= 0:
            raise ValueError('Withdrawal amount must be positive')
        if self._balance_cents < amount_cents:
            raise ValueError('Insufficient balance')
        self._balance_cents -= amount_cents


class TransferDomainService:
    def transfer(self, source_acc: BankAccountAggregate, target_acc: BankAccountAggregate, amount_cents: int, fee_cents: int = 0):
        if amount_cents <= 0:
            raise ValueError('Transfer amount must be positive')
        if fee_cents < 0:
            raise ValueError('Fee must be non-negative')
        if source_acc.account_id == target_acc.account_id:
            raise ValueError('Cannot transfer to same account')

        total_deduction = amount_cents + fee_cents
        source_acc.withdraw(total_deduction)
        try:
