class DomainPaymentRecord:
    def __init__(self, transaction_id: str, amount_cents: int, currency: str, status: str, is_final: bool):
        self.transaction_id = transaction_id
        self.amount_cents = amount_cents
        self.currency = currency
        self.status = status
        self.is_final = is_final

    def __eq__(self, other):
        if not isinstance(other, DomainPaymentRecord):
            return False
        return (self.transaction_id == other.transaction_id and
                self.amount_cents == other.amount_cents and
                self.currency == other.currency and
                self.status == other.status and
                self.is_final == other.is_final)


class LegacyBillingAdapter:
    STATUS_MAP = {
        1: 'PAID',
        2: 'PENDING',
        3: 'FAILED'
    }

    CURRENCY_MAP = {
        '$': 'USD',
        '€': 'EUR',
        '₽': 'RUB'
    }

    def translate_payment(self, raw_payload: dict) -> DomainPaymentRecord:
        if not isinstance(raw_payload, dict):
            raise ValueError('Corrupted legacy payload')

        tx_id = raw_payload.get('TxId')
        if not tx_id:
            raise ValueError('Corrupted legacy payload')

        raw_amount = raw_payload.get('AmountValue')
        if raw_amount is None:
            raise ValueError('Corrupted legacy payload')
        try:
            amount_cents = int(round(float(raw_amount) * 100))
            if amount_cents < 0:
                raise ValueError('Negative amount')
        except Exception as e:
            raise ValueError('Corrupted legacy payload') from e

        raw_curr = raw_payload.get('CurrencySign') or raw_payload.get('CurrencyCode')
        if not raw_curr:
            raise ValueError('Corrupted legacy payload')
        currency = self.CURRENCY_MAP.get(str(raw_curr).strip(), str(raw_curr).strip().upper())
        if len(currency) != 3:
            raise ValueError('Corrupted legacy payload')

        raw_status = raw_payload.get('TxStatusId')
        if raw_status not in self.STATUS_MAP:
            raise ValueError('Unknown legacy status')
        status = self.STATUS_MAP[raw_status]
        is_final = status in ('PAID', 'FAILED')

        return DomainPaymentRecord(
            transaction_id=str(tx_id),
            amount_cents=amount_cents,
            currency=currency,
            status=status,
            is_final=is_final
        )

